--根据数据库字符集编码的不同采用不同的字符长度判断方法,UTF-8使用lessThanCharLengthUTF8,GBK使用lessThanCharLength
update CHB_DATACHECK_RULE_INV set CHECKMETHOD = 'lessThanCharLengthUTF8' where CHECKMETHOD = 'lessThanCharLength';
update CHB_DATACHECK_CONDITION_INV set CHECKMETHOD = 'lessThanCharLengthUTF8' where CHECKMETHOD = 'lessThanCharLength';